using Htt.Infrastructure;
using Htt.SharedKernel;
using Htt.Host.Api.MasterData;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.Accounting;
public sealed record FiscalYearInput(string Label, DateOnly From, DateOnly To);
public sealed record AccountingCloseInput(string Reference,string Reason,bool BasNotApplicableConfirmed=false);
public sealed record RetainedEarningsInput(Guid AccountId,string Reason);
internal static class PeriodCloseEndpoints
{
 private static long Version(HttpContext h,bool zero=false){if(!long.TryParse(h.Request.Headers.IfMatch.ToString().Trim('"'),out var v)||v<(zero?0:1))throw new BusinessException("version_required","Current If-Match required.",428);return v;}
 private static Task<Dictionary<string,object?>> Period(CompanySession s,Guid id,CancellationToken ct)=>One(s,"SELECT * FROM accounting.periods WHERE company_id=@company AND id=@id",ct,new DbArg("id",id));
 private static Task<Dictionary<string,object?>> Year(CompanySession s,Guid id,CancellationToken ct)=>One(s,"SELECT y.*,k.state,k.version,k.current_closing_id FROM accounting.fiscal_years y JOIN accounting.fiscal_year_controls k USING(company_id,id) WHERE y.company_id=@company AND y.id=@id",ct,new DbArg("id",id));
 private static async Task<IResult> Query(CompanySession s,string sql,CancellationToken ct,params DbArg[] args)=>Results.Content((string)(await One(s,sql,ct,args))["result"]!,"application/json");
 public static void Map(RouteGroupBuilder g)
 {
  g=g.MapGroup("").AddEndpointFilter(async(context,next)=>{foreach(var cap in new[]{"accounting.periods.read","accounting.bas.read","accounting.ledger.read","accounting.gst.read","purchase.input_gst.read","accounting.reconciliation.read"})if(!Access(context.HttpContext).Has(cap))throw new BusinessException("permission_denied","Accounting close requires period, reconciliation, ledger, BAS and GST read permissions.",403);return await next(context);});
  g.MapGet("/accounting/fiscal-years",async(CompanySession s,CancellationToken ct)=>Results.Ok(new{items=(await Read(s,"SELECT y.*,k.state,k.version,k.current_closing_id FROM accounting.fiscal_years y JOIN accounting.fiscal_year_controls k USING(company_id,id) WHERE y.company_id=@company ORDER BY starts_on,id",ct)).Select(PublicRow)})).WithMetadata(new Permission("accounting.periods.read"));
  g.MapGet("/accounting/periods",async(Guid? fiscalYearId,CompanySession s,CancellationToken ct)=>Results.Ok(new{items=(await Read(s,"SELECT * FROM accounting.periods WHERE company_id=@company AND(@year IS NULL OR fiscal_year_id=@year)ORDER BY starts_on,id",ct,new DbArg("year",fiscalYearId,NpgsqlTypes.NpgsqlDbType.Uuid))).Select(PublicRow)})).WithMetadata(new Permission("accounting.periods.read"));
  g.MapGet("/accounting/periods/{id:guid}/preflight",async(Guid id,bool? basNotApplicableConfirmed,CompanySession s,CancellationToken ct)=>await Query(s,"SELECT accounting.period_preflight(@id,@na)::text AS result",ct,new DbArg("id",id),new DbArg("na",basNotApplicableConfirmed??false))).WithMetadata(new Permission("accounting.periods.read"));
  g.MapGet("/accounting/fiscal-years/{id:guid}/preflight",async(Guid id,CompanySession s,CancellationToken ct)=>await Query(s,"SELECT accounting.year_close_plan(@id)::text AS result",ct,new DbArg("id",id))).WithMetadata(new Permission("accounting.periods.read"));
  g.MapGet("/accounting/periods/{id:guid}/history",async(Guid id,CompanySession s,CancellationToken ct)=>{await Period(s,id,ct);return Results.Ok(new{snapshots=(await Read(s,"SELECT id,revision,financial_hash,reference,reason,created_at,created_by FROM accounting.period_close_snapshots WHERE company_id=@company AND period_id=@id ORDER BY revision",ct,new DbArg("id",id))).Select(PublicRow),events=(await Read(s,"SELECT * FROM accounting.period_close_events WHERE company_id=@company AND period_id=@id ORDER BY period_version",ct,new DbArg("id",id))).Select(PublicRow)});}).WithMetadata(new Permission("accounting.periods.read"));
  g.MapGet("/accounting/period-close-snapshots/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>await Query(s,"SELECT(to_jsonb(x))::text AS result FROM accounting.period_close_snapshots x WHERE company_id=@company AND id=@id",ct,new DbArg("id",id))).WithMetadata(new Permission("accounting.periods.read"));
  g.MapGet("/accounting/fiscal-years/{id:guid}/history",async(Guid id,CompanySession s,CancellationToken ct)=>{await Year(s,id,ct);return await Query(s,"SELECT jsonb_build_object('closings',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('profit',x.profit::text)ORDER BY revision) FROM accounting.year_end_closings x WHERE company_id=@company AND fiscal_year_id=@id),'[]'::jsonb),'reversals',coalesce((SELECT jsonb_agg(to_jsonb(r)ORDER BY r.created_at,r.id) FROM accounting.year_end_reversals r JOIN accounting.year_end_closings c ON c.company_id=r.company_id AND c.id=r.closing_id WHERE c.company_id=@company AND c.fiscal_year_id=@id),'[]'::jsonb))::text AS result",ct,new DbArg("id",id));}).WithMetadata(new Permission("accounting.periods.read"));
  g.MapGet("/accounting/retained-earnings",async(CompanySession s,CancellationToken ct)=>await Query(s,"SELECT jsonb_build_object('accountId',(SELECT account_id FROM accounting.account_mappings WHERE company_id=@company AND purpose='RETAINED_EARNINGS'),'version',coalesce((SELECT version FROM accounting.account_mappings WHERE company_id=@company AND purpose='RETAINED_EARNINGS'),0))::text AS result",ct)).WithMetadata(new Permission("accounting.periods.read"));
  g.MapPost("/accounting/fiscal-years",CreateYear).WithMetadata(new Permission("accounting.periods.manage"));
  g.MapPut("/accounting/retained-earnings",Configure).WithMetadata(new Permission("accounting.periods.manage"));
  foreach(var(year,path,cap)in new[]{(false,"close","accounting.periods.close"),(false,"reopen","accounting.periods.reopen"),(true,"close","accounting.years.close"),(true,"reopen","accounting.years.reopen")})g.MapPost("/accounting/"+(year?"fiscal-years":"periods")+"/{id:guid}/"+path,(Guid id,AccountingCloseInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>Transition(id,year,path,input,h,s,idem,ct)).WithMetadata(new Permission(cap));
 }
 private static async Task<IResult> CreateYear(FiscalYearInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {
  var label=Check.Text(input.Label,"label",200);Check.That(input.From.Year>=2&&input.From.Year<=9998&&input.From.Day==1&&input.To==input.From.AddYears(1),"from","Supply one full fiscal year.");var result=await idem.ExecuteAsync("POST /accounting/fiscal-years",h.Request.Headers["Idempotency-Key"].ToString(),Json(input with{Label=label}),async()=>{var id=(Guid)(await One(s,"SELECT accounting.create_fiscal_year(@label,@from,@to)AS id",ct,new DbArg("label",label),new DbArg("from",input.From),new DbArg("to",input.To)))["id"]!;await Sql.AuditAsync(s,"accounting.fiscal_year_created","fiscal_year",id,h.TraceIdentifier,ct);return ApiJson.Stored(PublicRow(await Year(s,id,ct)),201);},ct);return ApiJson.Result(result);
 }
 private static async Task<IResult> Transition(Guid id,bool year,string action,AccountingCloseInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {
  if(year)await Year(s,id,ct);else await Period(s,id,ct);var version=Version(h);var reference=Check.Text(input.Reference,"reference",200);var reason=Check.Text(input.Reason,"reason",2000);Check.That(!input.BasNotApplicableConfirmed||(!year&&action=="close"),"basNotApplicableConfirmed","This confirmation applies only to period close.");var path=$"POST /accounting/{(year?"fiscal-years":"periods")}/{id}/{action}";
  var result=await idem.ExecuteAsync(path,h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version,reference,reason,input.BasNotApplicableConfirmed}),async()=>{var fn=year?(action=="close"?"close_fiscal_year":"reopen_fiscal_year"):(action=="close"?"close_period":"reopen_period");var args=new List<DbArg>{new("id",id),new("version",version),new("reference",reference),new("reason",reason)};var extra="";if(!year&&action=="close"){extra=",@na";args.Add(new("na",input.BasNotApplicableConfirmed));}var row=await One(s,"SELECT accounting."+fn+"(@id,@version,@reference,@reason"+extra+")AS evidence_id",ct,args.ToArray());await Sql.AuditAsync(s,"accounting."+(year?"year_":"period_")+action,"fiscal_"+(year?"year":"period"),id,h.TraceIdentifier,ct,new{reference,reason,input.BasNotApplicableConfirmed});return ApiJson.Stored(new{entity=PublicRow(year?await Year(s,id,ct):await Period(s,id,ct)),evidenceId=row["evidence_id"]},200);},ct);return ApiJson.Result(result);
 }
 private static async Task<IResult> Configure(RetainedEarningsInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {
  var version=Version(h,true);var reason=Check.Text(input.Reason,"reason",2000);var result=await idem.ExecuteAsync("PUT /accounting/retained-earnings",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{version,input.AccountId,reason}),async()=>{var row=await One(s,"SELECT accounting.configure_retained(@id,@version)AS version",ct,new DbArg("id",input.AccountId),new DbArg("version",version));await Sql.AuditAsync(s,"accounting.retained_earnings_configured","account",input.AccountId,h.TraceIdentifier,ct,new{reason});return ApiJson.Stored(new{input.AccountId,version=row["version"]},200);},ct);return ApiJson.Result(result);
 }
}
